def clean_text(value): if not value: return '' return str(value).strip()
def first_text(*values): for value in values: value = clean_text(value) if value: return value return ''
def get_field(record, field_name): if field_name in record._fields: return record[field_name] return False
def get_text_field(record, field_name): value = get_field(record, field_name) return clean_text(value)
def get_linked_pool(applicant): for field_name in [ 'x_pool_id', 'x_hr_pool_id', 'x_pool_candidate_id', 'x_pool_candidate_record_id', 'x_candidate_pool_id', ]: value = get_field(applicant, field_name) if value and getattr(value, '_name', '') == 'x_hr.pool': return value return False
def display_name_ar(record): if not record: return '' return first_text( get_text_field(record.with_context(lang='ar_001'), 'name'), get_text_field(record, 'name'), record.display_name )
def duration_label(contract): value = contract.x_contract_duration_value or 0 unit = clean_text(contract.x_contract_duration_unit) if not value: return '' if unit == 'year': return str(value) + ' سنة' if unit == 'month': return str(value) + ' شهر' if unit == 'day': return str(value) + ' يوم' return str(value)
